```java
package com.mkii.coursemanagementsystem.dao.impl;

import com.mkii.coursemanagementsystem.dao.ICategoryDao;
import com.mkii.coursemanagementsystem.entity.Category;
import com.mkii.coursemanagementsystem.hibernateDao.HibernatePaginationSortingDao;
import jakarta.persistence.EntityManager;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Repository;
import java.util.List;

@Repository
public class CategoryDaoImpl extends HibernatePaginationSortingDao<Long, Category> implements ICategoryDao {

    @Autowired
    public CategoryDaoImpl(EntityManager entityManager) {
        super(Category.class, entityManager);
    }

    @Override
    public List<Category> findByName(String name) {
        String hql = "SELECT c FROM Category c WHERE LOWER(c.name) LIKE LOWER(CONCAT('%', :name, '%'))";
        return getEntityManager().createQuery(hql, Category.class)
                .setParameter("name", name)
                .getResultList();
    }
}
```

